BEGIN;
--
-- Create model Dish
--
CREATE TABLE "core_dish" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL UNIQUE, "description" text NOT NULL, "video_url" varchar(512) NOT NULL, "time_to_cook_minutes" smallint NOT NULL CHECK ("time_to_cook_minutes" >= 0), "recipe_steps" text NOT NULL, "special_instructions" text NOT NULL, "required_utensils" varchar(255) NOT NULL);
--
-- Create model Ingredient
--
CREATE TABLE "core_ingredient" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(100) NOT NULL UNIQUE);
--
-- Create model ServiceArea
--
CREATE TABLE "core_servicearea" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "pincode" varchar(10) NOT NULL UNIQUE, "city" varchar(50) NOT NULL, "name" varchar(100) NOT NULL);
--
-- Create model Cook
--
CREATE TABLE "core_cook" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "full_name" varchar(100) NOT NULL, "phone_number" varchar(20) NOT NULL UNIQUE, "has_set_availability" boolean NOT NULL, "wallet_balance" numeric(10, 2) NOT NULL, "availability_last_updated" timestamp with time zone NULL, "years_of_experience" smallint NOT NULL CHECK ("years_of_experience" >= 0), "onboarding_quiz_score" smallint NOT NULL CHECK ("onboarding_quiz_score" >= 0), "cooking_test_score" smallint NOT NULL CHECK ("cooking_test_score" >= 0), "overall_competence_score" double precision NOT NULL, "kyc_status" varchar(20) NOT NULL, "kyc_document_url" varchar(512) NOT NULL, "is_active" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, "user_id" integer NOT NULL UNIQUE);
CREATE TABLE "core_cook_certified_dishes" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "cook_id" bigint NOT NULL, "dish_id" bigint NOT NULL);
CREATE TABLE "core_cook_service_areas" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "cook_id" bigint NOT NULL, "servicearea_id" bigint NOT NULL);
--
-- Create model AvailabilitySlot
--
CREATE TABLE "core_availabilityslot" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "day_of_week" integer NOT NULL, "start_time" time NOT NULL, "end_time" time NOT NULL, "cook_id" bigint NOT NULL);
--
-- Create model DishIngredient
--
CREATE TABLE "core_dishingredient" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "quantity" numeric(7, 2) NOT NULL, "unit" varchar(5) NOT NULL, "is_must_have" boolean NOT NULL, "dish_id" bigint NOT NULL, "ingredient_id" bigint NOT NULL);
--
-- Add field ingredients to dish
--
-- (no-op)
--
-- Create model ScheduledTask
--
CREATE TABLE "core_scheduledtask" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "dish_name" varchar(150) NOT NULL, "date" date NOT NULL, "start_time" time NOT NULL, "cook_earnings" numeric(6, 2) NOT NULL, "status" varchar(20) NOT NULL, "cook_id" bigint NOT NULL);
CREATE INDEX "core_dish_name_72afa03c_like" ON "core_dish" ("name" varchar_pattern_ops);
