ALTER TABLE "core_scheduledtask" ADD CONSTRAINT "core_scheduledtask_cook_id_56be9c59_fk_core_cook_id" FOREIGN KEY ("cook_id") REFERENCES "core_cook" ("id") DEFERRABLE INITIALLY DEFERRED;
